'use client';
import ThemeIcon from "../themes/ThemeIcon";
import {useContext,useEffect,useId,useRef,useState,type CSSProperties,type ReactNode} from 'react';
import {ArrowRight,ArrowLeft,Plus,Minus,ShoppingBasket,ShoppingBag,Search,X,ArrowUpRight,Scale,FileText,ChevronDown} from 'lucide-react';
import {ZdxAppearanceContext} from './zdx-runtime';
import {REFINED_PRODUCTS,refinedMoney,refinedPrice,refinedFilter,refinedChange,refinedTotals,refinedCompare,type RefinedFamily,type RefinedProduct,type RefinedLine,type RefinedMarket} from './zdx-refined-data';
import Art,{FreshHarvest} from './ZdxRefinedArt';
import s from './zdx-refined.module.css';
import m from './fresh-motion.module.css';
import {useFreshShoppingMotion} from './useFreshShoppingMotion';
type View='home'|'collection'|'product'|'bag'|'compare'|'story';
const identities={
 'canvas':{brand:'Canvas',tag:'THE EVERYDAY COLLECTION / DESIGN DEMO',bg:'#FFFFFF',ink:'#171717',accent:'#171717',font:'"Instrument Sans", sans-serif'},
 'soho':{brand:'Soho',tag:'LONDON SIGNATURE / OBJECTS & EVERYDAY LIVING',bg:'#F5F4FA',ink:'#28263F',accent:'#5146A0',font:'"Instrument Sans", sans-serif'},
 'mayfair':{brand:'Mayfair',tag:'LONDON SIGNATURE / THE DEPARTMENT EDIT',bg:'#F7F5EE',ink:'#203A43',accent:'#B8492E',font:'"Instrument Sans", sans-serif'},
 'camden':{brand:'Camden',tag:'LONDON SIGNATURE / YOUR OWN WAY',bg:'#F1F0EC',ink:'#232326',accent:'#C82F3D',font:'"Bricolage Grotesque", sans-serif'},
 'atelier-minimal':{brand:'Forma',tag:'A STUDY IN LESS.',bg:'#E6F2F5',ink:'#173C49',accent:'#1E6378',font:'Jost, sans-serif'},
 'fresh-market':{brand:'Oja',tag:'GOOD FOOD. FAMILIAR ROOTS.',bg:'#fff4e8',ink:'#39223f',accent:'#542b58',font:'Nunito, sans-serif'},
 'african-editorial':{brand:'Ilé',tag:'CLOTH / CULTURE / EVERYDAY',bg:'#f9f3e9',ink:'#25231f',accent:'#963e27',font:'"Instrument Sans", sans-serif'},
 'spec-sheet':{brand:'Volt',tag:'A CLEARER WAY TO SPECIFY.',bg:'#0b1424',ink:'#e6eef9',accent:'#70b5f3',font:'"IBM Plex Sans", sans-serif'},
};
function useShop(family:RefinedFamily,initialScreen:string){
 const fresh=useFreshShoppingMotion(family==='fresh-market');
 const [basketOpen,setBasketOpen]=useState(false);
 const identity=identities[family],appearance=useContext(ZdxAppearanceContext),items=REFINED_PRODUCTS[family];
 const [view,setView]=useState<View>(['collection','product','bag'].includes(initialScreen)?initialScreen as View:'home');
 const [market,setMarket]=useState<RefinedMarket>(['mayfair','camden','soho','canvas'].includes(family)?'GB':'NG'),[query,setQuery]=useState(''),[category,setCategory]=useState('All'),[sort,setSort]=useState('edit');
 const [lines,setLines]=useState<RefinedLine[]>([]),[focusId,setFocusId]=useState(items[0].id),[size,setSize]=useState(''),[compared,setCompared]=useState<string[]>([]),[notice,setNotice]=useState('');
 const heading=useRef<HTMLHeadingElement>(null),focus=items.find(p=>p.id===focusId)!;
 const totals=refinedTotals(items,lines,market),shown=refinedFilter(items,query,category,sort,market),categories=['All',...new Set(items.map(p=>p.category))];
 const colours=appearance.colours;
 const style={...(family==='fresh-market'?{'--fresh-warm':colours?`color-mix(in srgb, ${colours.accent} 35%, ${colours.canvas})`:'#E9A18C','--fresh-soft':colours?`color-mix(in srgb, ${colours.accent} 12%, ${colours.canvas})`:'#F4DBE4'}:{}),'--r-bg':colours?.canvas||identity.bg,'--r-ink':colours?.ink||identity.ink,'--r-accent':colours?.accent||identity.accent,'--r-on':colours?.accentInk||(family==='spec-sheet'?'#0b1424':'#ffffff'),fontFamily:appearance.font||identity.font,'--r-display':appearance.font||(family==='african-editorial'?'Fraunces, Georgia, serif':family==='atelier-minimal'?'Cormorant Garamond, Georgia, serif':identity.font)} as CSSProperties;
 const go=(next:View)=>{setBasketOpen(false);setView(next);setNotice('');requestAnimationFrame(()=>{heading.current?.focus({preventScroll:true});heading.current?.scrollIntoView({block:'start',behavior:'instant'});});};
 const browse=(cat='All')=>{setCategory(cat);setQuery('');go('collection');};
 const open=(p:RefinedProduct)=>{setFocusId(p.id);setSize('');go('product');};
 const change=(p:RefinedProduct,delta:number,variant='',origin?:HTMLElement)=>{setLines(lines=>refinedChange(items,lines,p.id,variant,delta));if(origin&&delta>0)fresh.fly(p,origin);};
 const add=(p:RefinedProduct)=>{if(p.sizes&&!size){setNotice('Choose a size before adding this piece.');return;}change(p,1,p.sizes?size:'');setNotice(`${p.name}${p.sizes?` / ${size}`:''} added to your sample ${family==='spec-sheet'?'quote list':family==='fresh-market'?'basket':family==='canvas'?'cart':'bag'}.`);};
 const compare=(id:string)=>{if(compared.includes(id))setCompared(ids=>ids.filter(x=>x!==id));else if(compared.length<3)setCompared(ids=>[...ids,id]);else setNotice('Compare up to three sample products. Remove one to choose another.');};
 const title=(text:string,eyebrow?:string)=><div className={s.pageTitle}>{eyebrow&&<span className={s.eyebrow}>{eyebrow}</span>}<h1 ref={heading} tabIndex={-1}>{text}</h1></div>;
 return {family,fresh,basketOpen,setBasketOpen,identity,brand:appearance.brand||identity.brand,style,items,view,go,market,setMarket,query,setQuery,category,setCategory,sort,setSort,shown,categories,lines,totals,focus,size,setSize,compared,compare,notice,setNotice,heading,browse,open,change,add,title,money:(p:RefinedProduct,n=1)=>refinedMoney(refinedPrice(p,market)*n,market),format:(n:number)=>refinedMoney(n,market)};
}
type Shop=ReturnType<typeof useShop>;
function Shell({shop,children}:{shop:Shop;children:ReactNode}){
 const q=shop,editorial=q.family==='african-editorial',spec=q.family==='spec-sheet',fresh=q.family==='fresh-market';
 return <div ref={fresh?q.fresh.root:undefined} className={`${s.root} ${fresh?m.motion:''}`} data-refined={q.family} data-fresh-motion={fresh?(q.fresh.enabled?'on':'off'):undefined} style={q.style}>
  <div className={s.top}><span>{q.identity.tag}</span><label><span>Sample prices</span><select value={q.market} aria-label="Shopping market" onChange={e=>q.setMarket(e.target.value as RefinedMarket)}><option value="NG">Nigeria / NGN</option><option value="GB">UK / GBP</option></select></label></div>
  <header className={s.header}><button className={s.wordmark} onClick={()=>q.go('home')}>{q.brand}{editorial&&<small>THE EVERYDAY ISSUE</small>}</button><form className={s.search} onSubmit={e=>{e.preventDefault();q.setCategory('All');q.go('collection');}}><Search size={17}/><input value={q.query} onChange={e=>q.setQuery(e.target.value)} aria-label="Search sample products" placeholder={spec?'Search by model, SKU or specification':editorial?'Find a piece, cloth or colour':['atelier-minimal','mayfair','camden','soho','canvas'].includes(q.family)?'Find a piece or material':'What’s on your shopping list?'}/><button type="submit" aria-label="Submit search"><ArrowRight size={17}/></button></form><button className={s.bagButton} data-fresh-basket-target={fresh?'header':undefined} aria-haspopup={fresh?'dialog':undefined} onClick={()=>fresh?q.setBasketOpen(true):q.go('bag')}>{spec?<FileText size={18}/>:editorial?<ShoppingBag size={18}/>:<ShoppingBasket size={20}/>}<span>{spec?'Quote list':q.family==='canvas'?'Cart':editorial?'Bag':'Basket'}</span><b key={q.totals.count} className={fresh&&q.totals.count?m.tick:undefined}>{q.totals.count}</b></button></header>
  <nav className={s.nav} aria-label="Shop departments"><button onClick={()=>q.go('home')} aria-current={q.view==='home'?'page':undefined}>{editorial?'The issue':spec?'Overview':q.family==='atelier-minimal'?'The studio':q.family==='mayfair'?'The house':q.family==='camden'?'The edit':q.family==='canvas'?'Home':q.family==='soho'?'The studio':'The market'}</button>{q.categories.map(c=><button key={c} onClick={()=>q.browse(c)} aria-current={q.view==='collection'&&q.category===c?'page':undefined}>{c==='All'?(editorial||['atelier-minimal','mayfair','camden','soho','canvas'].includes(q.family)?'All pieces':spec?'All equipment':'All aisles'):c}</button>)}{editorial&&<button onClick={()=>q.go('story')}>Cloth notes <ArrowUpRight size={13}/></button>}{spec&&<button onClick={()=>q.go('compare')}>Compare ({q.compared.length})</button>}</nav>
  {q.notice&&<div className={s.notice} role="status"><span>{q.notice}</span><button onClick={()=>q.setNotice('')} aria-label="Dismiss message"><X size={18}/></button></div>}
  {fresh&&<span role="status" className={m.sr}>Sample basket: {q.totals.count} items. Items subtotal {q.format(q.totals.total)}.</span>}
  {children}
  <footer className={s.footer}><div><strong>{q.brand}</strong><p>{editorial?'Cloth with character. Space to be yourself.':spec?'Know the details. Make a considered choice.':q.family==='atelier-minimal'?'Fewer pieces. More possibility.':q.family==='mayfair'?'London-inspired. Considered for every day.':q.family==='camden'?'Your city. Your wardrobe. Your own way.':q.family==='canvas'?'Good things. Simply.':q.family==='soho'?'Objects with a point of view.':'The food you love. A market that feels like home.'}</p></div><div><button onClick={()=>q.browse()}>Explore the collection <ArrowRight size={16}/></button><button onClick={()=>q.go('bag')}>{spec?'Your sample quote list':editorial?'Your sample bag':'Your sample basket'} <ArrowRight size={16}/></button></div><small>Zayvi / {q.identity.brand} / design demonstration<br/>Sample products and prices. No real orders, quotes or payments.</small></footer>
  {q.family==='fresh-market'&&<button className={s.mobileBasket} data-fresh-basket-target="dock" aria-haspopup="dialog" onClick={()=>q.setBasketOpen(true)}><span data-fresh-basket-mouth className={m.basketMark} aria-hidden="true"><svg viewBox="0 0 80 64" fill="none"><path d="M22 26L34 5m24 21L46 5" stroke="currentColor" strokeWidth="5" strokeLinecap="round"/><path d="M10 27h60l-9 31H19z" fill="currentColor" fillOpacity=".16" stroke="currentColor" strokeWidth="4" strokeLinejoin="round"/><path d="M8 26h64M28 36l2 13m10-13v13m12-13-2 13" stroke="currentColor" strokeWidth="4" strokeLinecap="round"/></svg></span><span>Your basket · {q.totals.count}</span><strong key={q.totals.total} className={q.totals.count?m.tick:undefined}>{q.format(q.totals.total)}</strong><ArrowRight size={18}/></button>}
  {fresh&&<FreshBasketDrawer shop={q}/>}
  {spec&&q.compared.length>0&&q.view!=='compare'&&<div className={s.compareTray}><span><Scale size={17}/>{q.compared.length} of 3 selected</span><button disabled={q.compared.length<2} onClick={()=>q.go('compare')}>Compare side by side <ArrowRight size={16}/></button><button onClick={()=>q.compared.forEach(id=>q.compare(id))} aria-label="Clear comparison"><X size={17}/></button></div>}
 </div>;
}
function Stepper({shop:q,p,variant='',compact=false}:{shop:Shop;p:RefinedProduct;variant?:string;compact?:boolean}){
 const qty=q.lines.find(l=>l.id===p.id&&l.variant===variant)?.quantity||0;
 return <div className={`${s.stepper} ${compact?s.compact:''}`}><button disabled={qty===0} onClick={()=>q.change(p,-1,variant)} aria-label={`Remove one ${p.name}${variant?` size ${variant}`:''}`}><Minus size={15}/></button><span key={qty} className={q.family==='fresh-market'&&qty>0?m.tick:undefined} aria-label={`Quantity ${qty}`}>{qty}</span><button onClick={event=>q.change(p,1,variant,event.currentTarget)} aria-label={`Add one ${p.name}${variant?` size ${variant}`:''}`}><Plus size={15}/></button></div>;
}
function ProductCard({shop:q,p,index=0}:{shop:Shop;p:RefinedProduct;index?:number}){
 const fresh=q.family==='fresh-market',editorial=q.family==='african-editorial';
 return <article className={s.card} data-fresh-item={fresh?p.id:undefined} data-fresh-selected={fresh&&q.lines.some(l=>l.id===p.id)?'true':undefined}><div className={s.productArt} style={{'--product-colour':p.colour} as CSSProperties}><button onClick={()=>q.open(p)} aria-label={`View ${p.name}`}><Art product={p}/></button>{fresh&&q.lines.some(l=>l.id===p.id)&&<span className={m.inBasket}><ThemeIcon name="check"/>{" In your basket"}</span>}<span className={s.artCaption}>{editorial?`PLATE ${String(index+1).padStart(2,'0')} / SAMPLE DESIGN`:'SAMPLE ILLUSTRATION'}</span>{q.family==='spec-sheet'&&<label className={s.compareCheck}><input type="checkbox" checked={q.compared.includes(p.id)} onChange={()=>q.compare(p.id)}/> Compare</label>}</div><div className={s.cardInfo}><span className={s.eyebrow}>{editorial?p.note:fresh?p.category:p.note}</span><button className={s.productName} onClick={()=>q.open(p)}>{p.name}</button>{fresh?<p>{p.unit} <span>· {q.format(refinedPrice(p,q.market)/(p.pack||1))} / {p.basis}</span></p>:<p>{editorial?p.category:Object.entries(p.specs||{})[0]?.join(' / ')}</p>}<div className={s.cardBottom}><strong>{q.money(p)}</strong>{fresh?<Stepper shop={q} p={p} compact/>:<button className={s.textButton} onClick={()=>q.open(p)}>{editorial?'Discover':'Details'} <ArrowUpRight size={16}/></button>}</div></div></article>;
}
function BagSummary({shop:q,mini=false}:{shop:Shop;mini?:boolean}){
 const spec=q.family==='spec-sheet';
 return <aside className={s.summary}><span className={s.eyebrow}>{spec?'BUILD YOUR LIST':'ALL THE GOOD THINGS'}</span><h2>{spec?'Sample quote list':q.family==='fresh-market'?'Your basket':'Your selection'}<span>{q.totals.count}</span></h2>{mini&&<div className={s.miniLines}>{q.lines.length?q.lines.map(l=>{const p=q.items.find(p=>p.id===l.id)!;return <div key={l.id+l.variant}><span>{l.quantity} × {p.name}</span><strong>{q.money(p,l.quantity)}</strong></div>;}):<p>A little empty for now.<br/>Add a few favourites to get started.</p>}</div>}<div className={s.total}><span>{spec?'Illustrative subtotal':'Items subtotal'}</span><strong key={q.totals.total} className={q.family==='fresh-market'&&q.totals.count?m.tick:undefined}>{q.format(q.totals.total)}</strong></div><p className={s.small}>{spec?'Sample pricing only. No quote will be sent. Manufacturer documentation and compatibility have not been verified.':'Delivery and taxes are not calculated in this demo. Nothing will be ordered.'}</p>{mini?<button className={s.primary} data-fresh-basket-target={q.family==='fresh-market'?'summary':undefined} onClick={()=>q.family==='fresh-market'?q.setBasketOpen(true):q.go('bag')}>View sample basket <ArrowRight size={17}/></button>:<button className={s.primary} disabled={!q.totals.count} onClick={()=>q.setNotice(spec?'Your sample quote list is ready to review. No request was sent.':'You reached the end of this sample shopping journey. No order or payment was created.')}>{spec?'Review sample list':'Review demo summary'} <ArrowRight size={17}/></button>}</aside>;
}
function FreshBasketDrawer({shop:q}:{shop:Shop}){
 const dialog=useRef<HTMLDialogElement>(null),titleId=useId();
 const isOpen=q.basketOpen;
 useEffect(()=>{
  const panel=dialog.current;if(!panel)return;
  if(!isOpen){if(panel.open)panel.close();return;}
  const previousOverflow=document.body.style.overflow;
  document.body.style.overflow='hidden';
  if(!panel.open)panel.showModal();
  return()=>{if(panel.open)panel.close();document.body.style.overflow=previousOverflow;};
 },[isOpen]);
 return <dialog ref={dialog} className={m.drawer} aria-labelledby={titleId} onClose={()=>q.setBasketOpen(false)} onCancel={()=>q.setBasketOpen(false)} onClick={event=>{if(event.target===event.currentTarget)q.setBasketOpen(false);}}>
  <header className={m.drawerHead}><div><span className={s.eyebrow}>YOUR SAMPLE MARKET BASKET</span><h2 id={titleId}>All the good things.</h2></div><button onClick={()=>q.setBasketOpen(false)} aria-label="Close basket"><X size={21}/></button></header>
  <div className={m.drawerStatus}><ShoppingBasket size={18}/><span data-fresh-basket-target="drawer">{q.totals.count} sample {q.totals.count===1?'item':'items'}</span><strong key={q.totals.total} className={q.totals.count?m.tick:undefined}>{q.format(q.totals.total)}</strong></div>
  <div className={m.drawerBody}>{q.lines.length?q.lines.map(line=>{const p=q.items.find(p=>p.id===line.id)!;return <article className={m.drawerLine} data-fresh-item={p.id} key={p.id}><button className={m.drawerArt} onClick={()=>q.open(p)} aria-label={`View ${p.name}`}><Art product={p}/></button><div><button className={s.productName} onClick={()=>q.open(p)}>{p.name}</button><p>{p.unit} · {q.money(p)} per pack</p><Stepper shop={q} p={p}/></div><div className={m.drawerLineEnd}><strong>{q.money(p,line.quantity)}</strong><button onClick={()=>q.change(p,-line.quantity)} aria-label={`Remove ${p.name} from basket`}><X size={15}/></button></div></article>;}):<div className={m.drawerEmpty}><ShoppingBasket size={35}/><h3>Your next good meal starts here.</h3><p>Add a few sample ingredients from the market. Your shopping stays in this demo.</p><button className={s.primary} onClick={()=>q.setBasketOpen(false)}>Keep exploring <ArrowRight size={17}/></button></div>}</div>
  <footer className={m.drawerFoot}><div><span>Items subtotal</span><strong key={q.totals.total} className={q.totals.count?m.tick:undefined}>{q.format(q.totals.total)}</strong></div><p>Design simulation only. Delivery and taxes are not calculated. No order or payment will be created.</p><button className={s.primary} disabled={!q.lines.length} onClick={()=>q.go('bag')}>Review sample basket <ArrowRight size={18}/></button><button className={s.textButton} onClick={()=>q.setBasketOpen(false)}><ArrowLeft size={15}/> Continue shopping</button></footer>
 </dialog>;
}
function Bag({shop:q}:{shop:Shop}){
 const spec=q.family==='spec-sheet';
 return <main className={s.main}>{q.title(spec?'Your specification list':q.family==='fresh-market'?'Your market basket':q.family==='camden'?'Your bag':q.family==='canvas'?'Your cart':'Your order sheet',spec?'PREPARE. REVIEW. COMPARE.':'A FEW GOOD CHOICES')}{!q.lines.length?<div className={s.empty}><ShoppingBag size={30}/><h2>{spec?'Start with the right details.':'There’s room for something good.'}</h2><p>{spec?'Add sample equipment to build a list for review.':'Your sample bag is empty.'}</p><button className={s.primary} onClick={()=>q.browse()}>Explore {spec?'equipment':'the collection'} <ArrowRight size={16}/></button></div>:<div className={s.bagLayout}><div>{q.lines.map(line=>{const p=q.items.find(p=>p.id===line.id)!;return <article className={s.bagLine} key={p.id+line.variant}><button className={s.lineArt} onClick={()=>q.open(p)} aria-label={`View ${p.name}`}><Art product={p}/></button><div><span className={s.eyebrow}>{p.category}</span><button className={s.productName} onClick={()=>q.open(p)}>{p.name}</button><p>{line.variant?`Size ${line.variant}`:p.unit||p.note}</p><Stepper shop={q} p={p} variant={line.variant}/></div><div className={s.lineEnd}><strong>{q.money(p,line.quantity)}</strong><button onClick={()=>q.change(p,-line.quantity,line.variant)} aria-label={`Remove ${p.name}${line.variant?` size ${line.variant}`:''}`}>Remove</button></div></article>;})}{q.family==='fresh-market'&&<div className={s.deliveryNote}><h3>A note on delivery</h3><p>Delivery windows belong here when a store connects its shipping setup. This demo does not offer or reserve delivery slots.</p></div>}<button className={s.textButton} onClick={()=>q.browse()}><ArrowLeft size={16}/> Keep exploring</button></div><BagSummary shop={q}/></div>}</main>;
}
function Detail({shop:q}:{shop:Shop}){
 const p=q.focus,fresh=q.family==='fresh-market',spec=q.family==='spec-sheet';
 return <main className={s.main}><button className={s.textButton} onClick={()=>q.browse(p.category)}><ArrowLeft size={15}/> Back to {p.category}</button><div className={s.detail}><div className={s.detailArt} style={{'--product-colour':p.colour} as CSSProperties}><Art product={p}/><span className={s.artCaption}>SAMPLE ILLUSTRATION / NOT A PRODUCT PHOTOGRAPH</span></div><section className={s.detailInfo}>{q.title(p.name,p.note)}<strong className={s.detailPrice}>{q.money(p)}</strong>{fresh&&<p className={s.pack}>{p.unit} · {q.format(refinedPrice(p,q.market)/(p.pack||1))} / {p.basis}</p>}<p>{p.detail}</p>{p.sizes&&<fieldset className={s.sizes}><legend>Choose your size</legend>{p.sizes.map(size=><button key={size} aria-pressed={q.size===size} onClick={()=>q.setSize(size)}>{size}</button>)}</fieldset>}{spec&&<div className={s.specDetails}><dl>{Object.entries(p.specs||{}).map(([key,value])=><div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl><p>Demo specifications. A shared voltage or category does not establish compatibility.</p><button disabled className={s.outline}><FileText size={16}/> Manufacturer datasheet not supplied</button></div>}<div className={s.detailActions}>{fresh?<Stepper shop={q} p={p}/>:<button className={s.primary} onClick={()=>q.add(p)}>{spec?'Add to sample quote list':q.family==='canvas'?'Add to sample cart':'Add to sample bag'} <Plus size={17}/></button>}{spec&&<button className={s.outline} onClick={()=>q.compare(p.id)} aria-pressed={q.compared.includes(p.id)}><Scale size={16}/>{q.compared.includes(p.id)?'Selected':'Compare'}</button>}</div><p className={s.small}>{fresh?'Sample produce and pack sizes. Origin, availability, ingredients and allergens must be provided by the seller.':spec?'Illustrated sample equipment. No installation advice, live quote or real purchase.':'Illustrative garment design, material and care notes. No real stock or maker attribution.'}</p></section></div><section className={s.related}><div className={s.sectionHead}><h2>{fresh?'Round out your basket':spec?'More equipment to explore':'The story continues'}</h2></div><div className={s.productGrid}>{q.items.filter(x=>x.id!==p.id).slice(0,3).map((p,i)=><ProductCard key={p.id} shop={q} p={p} index={i}/>)}</div></section></main>;
}
function Listing({shop:q}:{shop:Shop}){return <main className={s.main}>{q.title(q.query?`Results for “${q.query}”`:q.category==='All'?(q.family==='african-editorial'?'The complete edit':q.family==='spec-sheet'?'Equipment index':q.family==='mayfair'?'All departments':q.family==='camden'?'The complete line-up':q.family==='atelier-minimal'?'The complete collection':q.family==='canvas'?'All products':q.family==='soho'?'The object index':'Walk the aisles'):q.category,'EXPLORE / SAMPLE COLLECTION')}<div className={s.listControls}><span>{q.shown.length} sample {q.shown.length===1?'item':'items'}</span><label>Category <select value={q.category} onChange={e=>q.setCategory(e.target.value)}>{q.categories.map(c=><option key={c}>{c}</option>)}</select></label><label>Sort <select value={q.sort} onChange={e=>q.setSort(e.target.value)}><option value="edit">The edit</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></label></div>{q.shown.length?(q.family==='spec-sheet'?<SpecIndex shop={q}/>:<div className={s.productGrid}>{q.shown.map((p,i)=><ProductCard key={p.id} shop={q} p={p} index={i}/>)}</div>):<div className={s.empty}><Search size={30}/><h2>Nothing in this edit yet.</h2><p>Try another search or clear your filters.</p><button className={s.primary} onClick={()=>q.browse()}>Show all sample products</button></div>}</main>;}
function SpecIndex({shop:q}:{shop:Shop}){return <div className={s.tableScroll} tabIndex={0} role="region" aria-label="Equipment specifications"><table className={s.specIndex}><thead><tr><th scope="col">Compare</th><th scope="col">Equipment / model</th><th scope="col">Category</th><th scope="col">Key specification</th><th scope="col">Sample price</th><th scope="col">Explore</th></tr></thead><tbody>{q.shown.map(p=><tr key={p.id}><td><input type="checkbox" aria-label={`Compare ${p.name}`} checked={q.compared.includes(p.id)} onChange={()=>q.compare(p.id)}/></td><th scope="row"><button onClick={()=>q.open(p)}><span className={s.tableArt}><Art product={p}/></span><span>{p.name}<small>{p.note}</small></span></button></th><td>{p.category}</td><td>{Object.entries(p.specs||{})[0]?.join(' / ')}</td><td>{q.money(p)}</td><td><button className={s.textButton} onClick={()=>q.open(p)}>Details <ArrowUpRight size={15}/></button></td></tr>)}</tbody></table></div>;}
function Compare({shop:q}:{shop:Shop}){
 const comparison=refinedCompare(q.items,q.compared);
 return <main className={s.main}>{q.title('The details, side by side.','COMPARE / UP TO THREE SAMPLES')}<p className={s.intro}>Compare illustrative fields, not compatibility. A dash means that field is not supplied for that sample.</p>{comparison.products.length<2?<div className={s.empty}><Scale size={32}/><h2>Choose at least two products.</h2><p>Select Compare on equipment cards or in the index.</p><button className={s.primary} onClick={()=>q.browse()}>Browse equipment</button></div>:<div className={s.tableScroll} tabIndex={0} role="region" aria-label="Side by side comparison"><table className={s.comparison}><thead><tr><th scope="col">Sample specifications</th>{comparison.products.map(p=><th scope="col" key={p.id}><Art product={p}/><button className={s.productName} onClick={()=>q.open(p)}>{p.name}</button><span>{q.money(p)}</span><button className={s.textButton} onClick={()=>q.compare(p.id)}>Remove <X size={13}/></button></th>)}</tr></thead><tbody>{comparison.rows.map(row=><tr key={row.key}><th scope="row">{row.key}</th>{row.values.map((value,i)=><td key={i}>{value}</td>)}</tr>)}<tr><th scope="row">Your list</th>{comparison.products.map(p=><td key={p.id}><button className={s.primary} onClick={()=>q.add(p)}>Add to sample list <Plus size={15}/></button></td>)}</tr></tbody></table></div>}</main>;
}
function Content({shop:q,home}:{shop:Shop;home:ReactNode}){return q.view==='bag'?<Bag shop={q}/>:q.view==='product'?<Detail shop={q}/>:q.view==='collection'?<Listing shop={q}/>:q.view==='compare'?<Compare shop={q}/>:home;}
