  <section className={s.meal} data-fresh-meal><div className={s.mealArt}>{meal.slice(0,3).map(p=><Art key={p.id} product={p}/>)}</div><div><span className={s.eyebrow}>A LITTLE MEAL INSPIRATION</span><h2>Something good<br/>is on the stove.</h2><p>Start a pantry basket with rice, tomatoes, palm oil and peppers. Four sample picks; season and adapt them your way.</p><div className={s.mealPrice}><strong>{q.format(meal.reduce((sum,p)=>sum+refinedPrice(p,q.market),0))}</strong><span>4 sample packs / items only</span></div><button className={s.primary} onClick={event=>bundle(event.currentTarget)}>Add the pantry picks <Plus size={18}/></button></div></section>
